    final String name;

    Cat(String name) {
        this.name = name;
    }

    void greet() {
        System.out.println(name + "：喵～");
    }
}

public class Main {
    public static void main(String[] args) {
        Cat a = new Cat("{cat}");
        a.greet();
    }
